async () => {
  const base = 'https://bitbucket.org/!api/2.0/repositories/healshealthcare/heals-app-rn';
  const pr = await (await fetch(base + '/pullrequests/559', {credentials:'include'})).json();
  const commits = await (await fetch(base + '/pullrequests/559/commits?pagelen=50', {credentials:'include'})).json();
  const diffstat = await (await fetch(base + '/pullrequests/559/diffstat?pagelen=100', {credentials:'include'})).json();
  return {
    id: pr.id,
    title: pr.title,
    state: pr.state,
    source: pr.source.branch.name,
    sourceHash: pr.source.commit.hash,
    dest: pr.destination.branch.name,
    destHash: pr.destination.commit.hash,
    commits: (commits.values||[]).map(c => ({hash: c.hash, message: (c.message||'').split('\n')[0], parents: (c.parents||[]).map(p => p.hash)})),
    files: (diffstat.values||[]).map(v => ({status: v.status, old: v.old && v.old.path, new: v.new && v.new.path, lines_added: v.lines_added, lines_removed: v.lines_removed}))
  };
}

