const ts = require('typescript');
const path = require('path');
const {execSync} = require('child_process');

const root = process.cwd();
const configPath = path.join(root, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
if (configFile.error) {
  console.error('readConfigFile error', configFile.error.messageText);
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, root);
console.log('TS', ts.version);
console.log('fileCount', parsed.fileNames.length);
console.log('options errors', parsed.errors.map(e => ts.flattenDiagnosticMessageText(e.messageText, '\n')));

const targets = [
  'src/screens/onboarding-screen/onboarding-screen.styles.ts',
  'src/screens/onboarding-screen/onboarding-screen.tsx',
];

function rel(fileName) {
  return path.relative(root, fileName);
}

function formatDiag(d) {
  const file = d.file && d.file.fileName ? rel(d.file.fileName) : '';
  const pos = d.file && d.start != null ? d.file.getLineAndCharacterOfPosition(d.start) : null;
  const loc = pos ? `${pos.line + 1}:${pos.character + 1}` : '';
  return {
    code: 'TS' + d.code,
    category: ts.DiagnosticCategory[d.category],
    file,
    loc,
    message: ts.flattenDiagnosticMessageText(d.messageText, '\n'),
  };
}

function collect(label, host) {
  const program = ts.createProgram({
    rootNames: parsed.fileNames,
    options: parsed.options,
    host,
  });
  const out = {};
  for (const relPath of targets) {
    const abs = path.join(root, relPath);
    const sf = program.getSourceFile(abs);
    if (!sf) {
      out[relPath] = {missing: true};
      continue;
    }
    const semantic = program.getSemanticDiagnostics(sf).map(formatDiag);
    const syntactic = program.getSyntacticDiagnostics(sf).map(formatDiag);
    const suggestions = program.getSuggestionDiagnostics(sf).map(formatDiag);
    out[relPath] = {syntactic, semantic, suggestions};
  }
  console.log('=== ' + label + ' ===');
  console.log(JSON.stringify(out, null, 2));
  return out;
}

const head = collect('HEAD');

const baseStyles = execSync('git show 53c9f9e26bb40cb1f63c9d4aef745a9c1aeaa663:src/screens/onboarding-screen/onboarding-screen.styles.ts', {encoding: 'utf8'});
const stylesAbs = path.join(root, targets[0]);
const host = ts.createCompilerHost(parsed.options, true);
const originalGet = host.getSourceFile.bind(host);
host.getSourceFile = (fileName, languageVersion, onError, shouldCreateNewSourceFile) => {
  if (path.resolve(fileName) === stylesAbs) {
    return ts.createSourceFile(fileName, baseStyles, languageVersion, true, ts.ScriptKind.TS);
  }
  return originalGet(fileName, languageVersion, onError, shouldCreateNewSourceFile);
};
collect('BASE styles overlay');
EOF
